import{d as c,C as t,o as u,c as b,j as a,a as o,E as r,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第四十章","description":"从反与弱，到有以无为本，理解道的运动、作用与万物所由。","frontmatter":{"title":"道德经第四十章","description":"从反与弱，到有以无为本，理解道的运动、作用与万物所由。","category":"guide","aliases":["道德经第四十章","老子第四十章","dao de jing chapter 40"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-40.md","filePath":"daoism/dao-de-jing/chapter-40.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-40.md"},P=c({...m,setup(f){const s=[{id:"return-as-movement",label:"反者道之动",showLabel:!0,sentences:[[{text:"反",glossary:"fan"},"者道之动，"]],note:["【白话】返归、回到所依的根本，是道的运动方式。依王弼，这也表现在高以低为基础、贵以贱为根本、有以无为作用条件的关系中。","【王弼注择要】「高以下为基，贵以贱为本，有以无为用，此其反也。」王弼直接承前章说明反，并说「动皆知其所无，则物通矣」。","【读法】反含返归及由相反一面看其所依的意思，不能据此认为任何趋势都会按固定时间表逆转；本页保留逗号，须连下一段读完首句。"]},{id:"softness-as-operation",label:"弱者道之用",showLabel:!0,sentences:[[{text:"弱",glossary:"ruo"},"者道之用。"]],note:["【白话】柔弱、不以刚强硬争，是道发挥作用的方式。它不靠固定、强占来限制万物，因而能够通达，作用不易穷尽。","【王弼注择要】「柔弱同通，不可穷极。」注把柔弱与通达、不尽之用相连，不只是在比较表面强度的大小。","【读法】本句的弱与第三十六章弱之的使之衰弱分义。这里强调柔顺的作用，不是宣称越无能力越有道，也不要求放弃必要的保护与行动。"]},{id:"being-grounded-in-nonbeing",label:"天下万物生于有，有生于无",showLabel:!0,sentences:[["天下万物生于",{text:"有",glossary:"you"},"，有生于",{text:"无",glossary:"wu"},"。"]],note:["【白话】天下万物由有而生，有又以无为所由始的根本。依王弼，要成全具体存在，便须返归无形无名、并不自限为某一物的根本，而不只在既成事物之间追逐。","【王弼注择要】「天下之物皆以有为生，有之所始，以无为本。」注最后说「将欲全有，必反于无也」，把生于有、生于无连到返本全有。","【读法】本页依王弼作所由与根本之论，不把无等同于物理真空或数学零，也不把两句改写成已经验证的宇宙生成时间表。反于无仍是为了全有，不是要否定万物的存在。"]}],n=[{id:"fan",term:"反",sense:1},{id:"ruo",term:"弱",sense:2},{id:"you",term:"有",sense:3},{id:"wu",term:"无",sense:3}];return(g,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四十章",tabindex:"-1"},[o("道德经第四十章 "),a("a",{class:"header-anchor",href:"#道德经第四十章","aria-label":'Permalink to "道德经第四十章"'},"​")],-1)),r(i,{title:"道的运动为什么称反，作用为什么称弱",summary:"本章只有两句，却从运动、作用说到万物的生成。王弼以前章高下、贵贱的依存解释反，以柔弱通达解释弱，再以有以无为本说明反归于无。",points:[{label:"先读",text:"反先取返归，并连高依下、贵依贱理解，不只等于朝相反方向做事。"},{label:"再辨",text:"弱写柔弱通达的作用，不能直接等同于失能或任人伤害。"},{label:"后看",text:"生于有、有生于无循王注返本解释，辨清它与现代物理生成说的不同。"}],hint:"反读 fǎn，取返归义；有、无在此循有形存在与无形无名之本来读，另列本章义项。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:s,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"反者道之动，弱者道之用。",tone:"返本与柔弱通达",guide:"从前章高下、贵贱的依存读反，再看柔弱何以成为可通不尽的作用。"},{text:"天下万物生于有，有生于无。",tone:"全有须反于无",guide:"循王注把万物的具体存在与其所由始的根本相连，勿把无化成另一件有形之物。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-两句短文怎样形成一章" tabindex="-1">象：两句短文怎样形成一章？ <a class="header-anchor" href="#象-两句短文怎样形成一章" aria-label="Permalink to &quot;象：两句短文怎样形成一章？&quot;">​</a></h3><p>第一句分别说运动之反、作用之弱，第二句再说万物生于有而有以无为本。王弼用将欲全有、必反于无贯通两句，使返归并不离开万物的成全。</p><h3 id="理-为什么返于无仍是为了全有" tabindex="-1">理：为什么返于无仍是为了全有？ <a class="header-anchor" href="#理-为什么返于无仍是为了全有" aria-label="Permalink to &quot;理：为什么返于无仍是为了全有？&quot;">​</a></h3><p>若把无当作取消一切存在，便难解释王弼的全有。注所强调的是：具体事物不能以自己的既成形态充当全部根本；回到不受某一形名拘限的所由，才可能成全不同的有。</p><h3 id="用-现代生活能怎样类比返本与柔弱" tabindex="-1">用：现代生活能怎样类比返本与柔弱？ <a class="header-anchor" href="#用-现代生活能怎样类比返本与柔弱" aria-label="Permalink to &quot;用：现代生活能怎样类比返本与柔弱？&quot;">​</a></h3><p>可以在事务僵化时回看它原要成全的需要，并给不同情况留下调整余地。这样的类比可帮助行动，却不能直接把无解释成没有规则、没有资源，也不能以柔弱替代实际能力。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>僵住时回到起初的问题。</strong> 一项方法或制度失去作用时，先问它原来为谁解决什么，再决定保留与调整什么。回到根本应帮助具体事情重新成立。</p><p><strong>给行动留下调整余地。</strong> 不把一次判断变成永远的唯一方案，允许新的事实改变做法。柔顺可以体现为有能力回应变化，而不是只把要求压低。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是否把某个既成的方法当成了根本？回到最初要成全的需要时，哪些执定可以松开，哪些责任仍须承担？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本章正文与标点沿本站保留，与所据卷三 005b 电子录文相核。</li><li>反依王弼高下、贵贱、有无相依及返本解释；弱另列柔弱、柔顺之义，与弱之的使动义分开。</li><li>有、无另列本章循王弼所采用的有形存在与无形无名之本义项，不以第十一章器物材料和空处的义项代替，也不据此宣称全书各章只有同一种有无解释。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，005b</a>。</p>',15))])}}});export{_ as __pageData,P as default};
